import{r as l,j as a}from"./index-BiwJYs6c.js";const t=[{title:"Sāc ar galveno izvēlni",icon:"🧭",description:"Datorā galvenās sadaļas atrodas kreisajā navigācijas joslā. Telefonā izmanto apakšējo navigāciju; pārējās sadaļas atver ar “Vairāk”.",tips:["Telefonā apakšējā joslā vienmēr pieejami Sākums, Kalendārs, Lietotāji un Albumi.","Pieskaries “Vairāk”, lai atvērtu Radu pērles, Manus notikumus, Ceļvedi un Iestatījumus.","Profila avatārs mobilās lapas augšā un profila kartīte datorā ved uz tavu profilu.","Datorā profila izvēlnē pieejami Iestatījumi un izrakstīšanās.","Lai atgrieztos sākumā, izvēlies “Sākums” vai vietnes logo."]},{title:"Sakārto savu profilu",icon:"👤",description:"Profila redaktorā vari pielāgot profila izskatu un izvēlēties, kādu informāciju vēlies parādīt ģimenes locekļiem.",tips:["Sadaļā “Dizains” izvēlies komplektu, pielāgo fona un akcenta krāsu vai atjauno noklusējuma dizainu.","Sadaļā “Profila informācija” vari pievienot aprakstu, iesauku, dzīvesvietu, hobijus, citātu un papildu informāciju. Dzīvesvietas attēlošanu vari izslēgt.","Sadaļā “Attēli” pievieno vai noņem vāka un profila attēlu; vāka attēla novietojumu vari pielāgot.","Sadaļā “Dekorācijas” izvēlies rotājumus un profila attēla rāmi.","Pēc izmaiņām spied “Saglabāt izmaiņas”. Dzimšanas dienas noformējums aktivizējas automātiski tavā dzimšanas dienā."]},{title:"Apskati ģimenes locekļus",icon:"👨‍👩‍👧‍👦",description:"Sadaļā “Lietotāji” redzami apstiprinātie ģimenes locekļi un viņu kopīgotie profili.",tips:["Izmanto meklēšanas lauku, lai atrastu cilvēku pēc vārda, uzvārda vai iesaukas.","Pieskaries profila kartītei, lai atvērtu profila logu; atsevišķa pilna profila lapa netiek atvērta.","Profilā vari apskatīt cilvēka aprakstu, citātu, hobijus un svarīgos datumus.","Dzīvesvieta redzama tikai tad, ja profila īpašnieks to ir atļāvis parādīt."]},{title:"Lasi un pārlūko kalendāru",icon:"📅",description:"Mēneša režģī katra rūtiņa ir viena diena. Uzspied uz tās, lai atvērtu dienas informāciju — datorā tā redzama blakus režģim, bet telefonā zem tā.",tips:["Izmanto bultiņas pa kreisi un pa labi, lai pārietu uz iepriekšējo vai nākamo mēnesi.","Spied “Šodien”, lai uzreiz atgrieztos pie pašreizējā mēneša.","Krāsainie punkti rāda vārda dienas, uzvārda dienas, dzimšanas dienas un ģimenes notikumus. Leģenda zem režģa paskaidro krāsas.","Dienas informācijā redzami vārda un uzvārda dienu vārdi, sakritības ar ģimenes locekļiem, dzimšanas dienas un pieejamie pasākumi.","Telefonā šūnā redzams datums un notikumu punkti; pārvelc pa kreisi vai pa labi, lai mainītu mēnesi.","Pasākuma detaļās apskati aprakstu, laiku un vietu."]},{title:"Pievieno pasākumu kalendāram",icon:"➕",description:"Datorā spied kalendāra augšdaļā “Jauns notikums”; telefonā izmanto peldošo “Jauns notikums” pogu. Aizpildi formu un spied “Pievienot”. Nosaukums un datums ir obligāti.",tips:["Laukā “Nosaukums” ieraksti īsu, saprotamu pasākuma nosaukumu, piemēram, “Ģimenes pikniks”.","Aprakstā pievieno papildu informāciju, ko pārējiem der zināt.","Izvēlies datumu kalendāra atlasītājā. Ja pasākumam ir noteikts sākuma laiks, ievadi to 24 stundu formātā HH:mm, piemēram, 18:30.","Laukā “Atrašanās vieta” ieraksti vietu, kur pasākums notiks.","Atzīmē “Atkārtojas katru gadu”, ja pasākums katru gadu notiek tajā pašā datumā.","Pasākums pēc noklusējuma ir kopīgs. Atzīmē “Privāts pasākums”, ja tam jābūt redzamam tikai tev un izvēlētajiem cilvēkiem, un tad atzīmē, kuri lietotāji to drīkst redzēt.","Pārbaudi ievadīto informāciju un spied “Pievienot”. Pasākumam jāparādās attiecīgajā kalendāra datumā un tavā notikumu sarakstā."]},{title:"Pārvaldi savus notikumus",icon:"🗂️",description:"Sadaļā “Notikumi” ir tavi pievienotie pasākumi. Katrs pasākums tiek parādīts atsevišķā kartītē ar nosaukumu, datumu un, ja tie norādīti, aprakstu, laiku un vietu.",tips:["Kartītes atzīme “Publisks” vai “Privāts” parāda, kam pasākums ir redzams. Ikgadējiem pasākumiem ir arī atzīme “Atkārtojas katru gadu”.","Lai mainītu pasākumu, atver tā kartīti un spied “Labot”. Maini nosaukumu vai datumu un, ja vajag, aprakstu, vietu vai laiku.","Rediģēšanas logā vari mainīt arī ikgadējo atkārtošanos un publiskuma iestatījumu. Privātam pasākumam atzīmē konkrētos cilvēkus, kuri to drīkst redzēt.","Pēc labojumiem spied “Saglabāt”. Ja pārdomāji, spied “Atcelt”, lai aizvērtu logu nesaglabājot izmaiņas.","Lai noņemtu pasākumu, spied “Dzēst” un apstiprini dzēšanu tikai tad, ja esi pārliecināts."]},{title:"Izveido foto albumu",icon:"📚",description:"Sadaļā “Albumi” spied “Jauns albums”. Vienā reizē vari izveidot albumu un pievienot tam vienu vai vairākus fotoattēlus.",tips:["Ieraksti albuma nosaukumu. Kategorija, emoji un apraksts palīdz albumu vēlāk vieglāk atpazīt.","Laukā “Atlasīt vairākus foto vienlaikus” izvēlies vairākus attēlu failus. Katram attēlam vari pievienot savu nosaukumu un piezīmi.","Ja gribi pievienot foto pa vienam vai pievienot vēl atsevišķus foto ierakstus, izmanto pogu “+ Foto rinda”. Nevajadzīgu rindu vari noņemt.","Pirms saglabāšanas pārbaudi attēlu priekšskatījumus, failu nosaukumus un piezīmes.","Albums sākotnēji ir publisks. Spied “Padarīt privātu”, lai ierobežotu redzamību, un atzīmē cilvēkus, kuriem vēlies albumu kopīgot.","Kad viss gatavs, spied “Saglabāt albumu”. Albums parādīsies albumu sarakstā."]},{title:"Apskati un atjauno albumus",icon:"🖼️",description:"Albumu sarakstā izvēlies albumu, lai atvērtu tā foto. Spied uz fotoattēla, lai to skatītu lielā skatā. Albuma veidotājs var labot albumu un tā fotoattēlus.",tips:["Ja albumu ir daudz, izmanto “Iepriekšējie albumi” un “Nākamie albumi”, lai pārietu starp saraksta lapām.","Foto skatītājā izmanto bultiņas, lai pārietu uz iepriekšējo vai nākamo attēlu; ar aizvēršanas pogu atgriezies albumā.","Spied “❤️ Patīk”, lai pievienotu savu reakciju. Ja vēlies to atsaukt, spied “Noņemt reakciju”.","Lai albumam pievienotu attēlus vēlāk, spied “Pievienot vēl foto”, izvēlies failus, pēc vajadzības ieraksti nosaukumus un piezīmes, tad spied “Pievienot foto”.","Albuma veidotājs var ar “Labot albumu” mainīt nosaukumu, aprakstu, kategoriju un privātuma iestatījumus.","Foto skatītājā albuma veidotājs var izvēlēties “Labot foto”, lai mainītu nosaukumu, piezīmi vai pašu attēlu.","Albuma vai foto dzēšana ir neatgriezeniska darbība. Pirms apstiprināšanas pārliecinies, ka izvēlēts pareizais albums vai attēls."]},{title:"Dalies ar Radu pērlēm",icon:"💎",description:"Radu pērles ir ģimenes atmiņu, citātu un stāstu krātuve, kurā vari dalīties ar tekstu, fotoattēliem un video.",tips:["Meklē pērles pēc nosaukuma vai citāta un izvēlies kategoriju, lai sašaurinātu sarakstu.","Spied “Pievienot pērli”, ievadi nosaukumu, kategoriju un stāstu vai citātu; konteksts ir neobligāts.","Pievieno līdz astoņiem fotoattēliem vai video un apskati to priekšskatījumus pirms iesniegšanas.","Atzīmē “Iesniegt anonīmi”, ja nevēlies, lai pie pērles būtu redzams tavs vārds.","Izmanto reakcijas pie pērles. Pieskaroties savai aktīvajai reakcijai vēlreiz, vari to noņemt."]},{title:"Iestati paziņojumus",icon:"🔔",description:"Iestatījumos vari pārvaldīt paziņojumus šajā ierīcē un atgādinājumus par savām svarīgajām kalendāra dienām.",tips:["Telefonā atver “Vairāk” → “Iestatījumi”; datorā atver profila izvēlni un izvēlies “Iestatījumi”.","Sadaļā “Push paziņojumi” spied “Ieslēgt paziņojumus šajā ierīcē” un apstiprini pārlūka pieprasīto atļauju.","Sadaļā “Kalendāra atgādinājumi” ieslēdz vai izslēdz atgādinājumu dienu iepriekš par savu vārda, uzvārda vai dzimšanas dienu.","Push atgādinājumiem vajadzīgs aktīvs ierīces abonements. Ja atļauja pārlūkā ir liegta, maini to pārlūka iestatījumos."]},{title:"Sākums, jaunumi un idejas",icon:"✨",description:"Sākumlapā redzami šodienas un tuvākie ģimenes datumi, kā arī vietnes jaunumi un atsauksmju forma.",tips:["Pārskati šodienas vārda dienas, uzvārda dienas, ģimenes notikumus un tuvākos datumus.","Spied “Jaunākie atjauninājumi”, lai atvērtu vietnes jaunumus un apskatītu pievienotās iespējas.","Sadaļā “Atsauksmes un idejas” izvēlies ziņas veidu, uzraksti vismaz piecus simbolus un spied “Nosūtīt”.","Atsauksme vai ideja tiek nosūtīta privāti vietnes veidotājam."]}];function m(){const[e,r]=l.useState(0),u=t[e],n=(e+1)/t.length*100;return a.jsxs("div",{className:"relative min-h-[calc(100vh-72px)] overflow-hidden py-8 sm:py-12",children:[a.jsx("div",{className:"pointer-events-none absolute inset-0 hero-grid opacity-30"}),a.jsxs("div",{className:"section-shell relative z-10",children:[a.jsxs("header",{className:"mx-auto mb-7 max-w-3xl text-center",children:[a.jsxs("div",{className:"eyebrow justify-center",children:[a.jsx("span",{"aria-hidden":"true",children:"✦"}),a.jsx("span",{children:"Vietnes lietošanas ceļvedis"})]}),a.jsx("h1",{className:"mt-3 text-3xl font-black tracking-tight text-dark-purple sm:text-5xl",children:"Iepazīsti vietni soli pa solim"}),a.jsx("p",{className:"mx-auto mt-4 max-w-2xl text-sm leading-7 text-muted sm:text-base",children:"Šeit atradīsi norādes par vietnes sadaļām un to iespējām. Izvēlies soli sarakstā vai ej cauri ceļvedim secīgi, izmantojot pogas apakšā."})]}),a.jsxs("section",{className:"mx-auto max-w-5xl overflow-hidden rounded-[1.75rem] border border-white/80 bg-white/90 shadow-[0_20px_60px_rgba(45,35,46,0.10)] backdrop-blur-xl",children:[a.jsxs("div",{className:"border-b border-[#e0ddcf] px-5 py-5 sm:px-8",children:[a.jsxs("div",{className:"mb-3 flex items-center justify-between gap-4 text-sm",children:[a.jsxs("span",{className:"font-bold text-dark-purple",children:["Solis ",e+1," no ",t.length]}),a.jsxs("span",{className:"text-muted",children:[Math.round(n),"% pabeigts"]})]}),a.jsx("div",{className:"h-2 overflow-hidden rounded-full bg-[#e0ddcf]",role:"progressbar","aria-label":"Ceļveža progress","aria-valuemin":0,"aria-valuemax":t.length,"aria-valuenow":e+1,children:a.jsx("div",{className:"h-full rounded-full bg-[#2d232e] transition-[width] duration-300",style:{width:`${n}%`}})})]}),a.jsxs("div",{className:"grid lg:grid-cols-[260px_minmax(0,1fr)]",children:[a.jsx("nav",{"aria-label":"Ceļveža soļi",className:"grid grid-cols-2 gap-2 border-b border-[#e0ddcf] p-4 sm:grid-cols-3 lg:flex lg:max-h-[70vh] lg:flex-col lg:overflow-y-auto lg:border-b-0 lg:border-r lg:p-5",children:t.map((i,s)=>a.jsxs("button",{type:"button","aria-current":s===e?"step":void 0,onClick:()=>r(s),className:`flex min-w-0 items-start gap-2 rounded-xl px-2.5 py-3 text-left text-sm font-bold leading-5 transition focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#534b52] sm:items-center sm:gap-3 sm:px-3 lg:w-full ${s===e?"bg-[#f1f0ea] text-[#2d232e]":"text-muted hover:bg-[#f1f0ea] hover:text-dark-purple"}`,children:[a.jsx("span",{className:"shrink-0 text-lg","aria-hidden":"true",children:i.icon}),a.jsx("span",{className:"min-w-0 break-words",children:i.title})]},i.title))}),a.jsxs("article",{className:"flex min-h-[390px] flex-col p-5 sm:p-8",children:[a.jsxs("div",{className:"flex-1",children:[a.jsx("div",{className:"mb-4 flex h-12 w-12 items-center justify-center rounded-2xl bg-[#f1f0ea] text-2xl","aria-hidden":"true",children:u.icon}),a.jsx("h2",{className:"text-2xl font-black text-dark-purple sm:text-3xl",children:u.title}),a.jsx("p",{className:"mt-4 text-sm leading-7 text-muted sm:text-base",children:u.description}),a.jsx("h3",{className:"mt-6 text-sm font-extrabold uppercase tracking-wide text-dark-purple",children:"Kā rīkoties"}),a.jsx("ol",{className:"mt-3 grid gap-3",children:u.tips.map((i,s)=>a.jsxs("li",{className:"flex gap-3 rounded-xl border border-[#e0ddcf] bg-[#faf9f6] px-4 py-3 text-sm leading-6 text-dark-purple",children:[a.jsx("span",{className:"flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-[#2d232e] text-xs font-black text-white",children:s+1}),a.jsx("span",{children:i})]},i))})]}),a.jsxs("div",{className:"mt-8 flex flex-col-reverse items-stretch gap-3 border-t border-[#e0ddcf] pt-5 sm:flex-row sm:items-center sm:justify-between",children:[a.jsx("button",{type:"button",onClick:()=>r(i=>Math.max(0,i-1)),disabled:e===0,className:"btn-ghost px-4 py-2.5 disabled:cursor-not-allowed disabled:opacity-40",children:"← Iepriekšējais"}),a.jsx("button",{type:"button",onClick:()=>r(i=>Math.min(t.length-1,i+1)),disabled:e===t.length-1,className:"btn-primary px-4 py-2.5 disabled:cursor-not-allowed disabled:opacity-40",children:"Nākamais →"})]})]})]})]})]})]})}export{m as default};
